import re
from typing import List, Dict, Any, Tuple

# Helpers are assumed to be provided externally
# node_by_title(doc, title)
# node_by_id(doc, node_id)
# children(doc, node)
# table_rows(node) -> [(row_index, {col: cell, ...}), ...]

# ------------------------------------------------------------------
# Utility helpers
# ------------------------------------------------------------------
def _get_products(node):
    """Return a list of product ids found in the Products table of the given scope node."""
    prod_rows = []
    for _, row in table_rows(node):
        prod_id = row.get('product')
        if prod_id:
            prod_rows.append((prod_id, row))
    return prod_rows

def _day_from_str(cell: str) -> int:
    """Parse day number from a cell string like '1' or '14'."""
    try:
        return int(cell)
    except Exception:
        return None

def _parse_capacity_line(line: str) -> Tuple[int, float, float]:
    """Parse a capacity reached line.
    Returns (day, cap_used, cap_total)."""
    m = re.search(r'Day (\d+).*?: dispatch capacity reached \(([\d\.]+) of ([\d\.]+) kg dispatched\)', line)
    if m:
        return int(m.group(1)), float(m.group(2)), float(m.group(3))
    return None

def _parse_runout_line(line: str) -> Tuple[int, str, int]:
    """Parse a run‑out line.
    Returns (day, product_id, backordered)."""
    m = re.search(r'Day (\d+).*?: (\S+) runs out of stock \((\d+) units backordered\)', line)
    if m:
        return int(m.group(1)), m.group(2), int(m.group(3))
    return None

def _parse_full_backorder_line(line: str) -> Tuple[int, str]:
    """Parse a full backorder line.
    Returns (day, product_id)."""
    m = re.search(r'Day (\d+).*?: (\S+) is fully backordered', line)
    if m:
        return int(m.group(1)), m.group(2)
    return None

def _parse_backlog_cleared_line(line: str) -> Tuple[int, str]:
    """Parse a backlog cleared line.
    Returns (day, product_id)."""
    m = re.search(r'Day (\d+).*?: (\S+) backlog cleared', line)
    if m:
        return int(m.group(1)), m.group(2)
    return None

def _find_node_by_title(doc, title):
    """Return the node dict with the given title."""
    for node in doc['nodes']:
        if node.get('title') == title:
            return node
    return None

# ------------------------------------------------------------------
# Main reading functions
# ------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Return list of dicts {"id": str, "description": str} for each product in the scope.
    """
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node:
        return []

    # Find the Products table under this scope
    prod_table = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'table' and child.get('title', '').endswith(': Products'):
            prod_table = child
            break
    if not prod_table:
        return []

    entities_list = []
    for _, row in table_rows(prod_table):
        prod_code = row.get('product')
        if not prod_code:
            continue
        description = f"{prod_code} ({row.get('group', '')}/{row.get('sub-group', '')})"
        entities_list.append({"id": prod_code, "description": description})
    return entities_list


def recorded_end(doc: Dict[str, Any], scope: str):
    """
    Return the last day number covered by the scope's records.
    """
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node:
        return None

    # Find the Daily ledger table
    ledger_table = None
    for child_id in scope_node.get('children', []):
        child = node_by_id(doc, child_id)
        if child and child.get('kind') == 'table' and child.get('title', '').endswith(': Daily ledger'):
            ledger_table = child
            break
    if not ledger_table:
        return None

    max_day = None
    for _, row in table_rows(ledger_table):
        day = _day_from_str(row.get('day', ''))
        if day is not None:
            if max_day is None or day > max_day:
                max_day = day
    return max_day


def inputs(doc: Dict[str, Any], scope: str):
    """
    Return list of inputs for the given scope.
    """
    scope_node = _find_node_by_title(doc, scope)
    if not scope_node:
