    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child and child.get("kind") == "table" and child.get("title", "").endswith(": Products"):
            prod_table = child
            break
    if not prod_table:
        return []

    result = []
    for _, row in table_rows(prod_table):
        prod_id = row.get("product")
        if not prod_id:
            continue
        grp = row.get("group", "")
        subgrp = row.get("sub-group", "")
        desc = f"{prod_id} ({grp}/{subgrp})"
        result.append({"id": prod_id, "description": desc})
    return result

# ------------------------------------------------------------------
# 2. Recorded end time
# ------------------------------------------------------------------
def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last day number covered by the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    ledger_table = None
    for child_id in scope_node.get("children", []):
        child = node_by_id(doc, child_id)
        if child and child.get("kind") == "table" and child.get("title", "").endswith(": Daily ledger"):
            ledger_table = child
            break
    if not ledger_table:
        return None
    max_day = None
    for _, row in table_rows(ledger_table):
        d = _parse_day(row.get("day", ""))
        if d is not None:
            max_day = d if max_day is None or d > max_day else max_day
    return float(max_day) if max_day is not None else None

# ------------------------------------------------------------------
# 3. Inputs
# ------------------------------------------------------------------
def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return the list of input records for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Build map of child titles to node
    nodes_map = {node_by_id(doc, cid)["title"]: node_by_id(doc, cid)
                 for cid in scope_node.get("children", [])
                 if node_by_id(doc, cid) is not None}

    result = []

    # Opening stock (state)
    prod_table = nodes_map.get(f"{scope}: Products")
    if prod_table:
        node_id = prod_table["node_id"]
        for row_idx, row in table_rows(prod_table):
            prod_id = row.get("product")
            if not prod_id:
                continue
            open_stock_s = row.get("opening stock", "0")
            try:
                open_stock = int(open_stock_s)
            except Exception:
                open_stock = 0
            result.append({
                "id": f"{prod_id}_open_stock",
                "time": None,
                "kind": "state",
                "entities": [prod_id],
                "fields": {"opening_stock": open_stock},
                "src": [[node_id, row_idx, ["product", "opening stock"]]],
            })

    # Daily ledger – production arrival and orders
    ledger_table = nodes_map.get(f"{scope}: Daily ledger")
    if ledger_table:
        node_id = ledger_table["node_id"]
        for row_idx, row in table_rows(ledger_table):
            day = _parse_day(row.get("day", ""))
            prod_id = row.get("product")
            if day is None or not prod_id:
                continue
            # Production arrival
            produced = int(row.get("produced", "0"))
            result.append({
                "id": f"{prod_id}_prod_day_{day}",
                "time": day,
                "kind": "arrival",
                "entities": [prod_id],
                "fields": {"produced": produced},
                "src": [[node_id, row_idx, ["day", "product", "produced"]]],
            })
            # Orders
            ordered = int(row.get("ordered", "0"))
            if ordered > 0:
                result.append({
                    "id": f"{prod_id}_order_day_{day}",
                    "time": day,
                    "kind": "order",
                    "entities": [prod_id],
                    "fields": {"ordered": ordered},
                    "src": [[node_id, row_idx, ["day", "product", "ordered"]]],
                })

    # Order book – future inputs / state of open orders
    order_book_table = None
    for key, tbl in nodes_map.items():
        if key.endswith(": Order book"):
            order_book_table = tbl
            break
    if order_book_table:
        node_id = order_book_table["node_id"]
        for row_idx, row in table_rows(order_book_table):
            # Detect column layout variant
            cols = set(row.keys())
            prod_id = row.get("product")
            if not prod_id:
                continue

            # Variant with day placed and units still open
            if "day placed" in cols and "units still open" in cols:
                day = _parse_day(row.get("day placed", ""))
                units_open = int(row.get("units still open", "0"))
                if day is not None:
                    result.append({
                        "id": f"{prod_id}_open_order_day_{day}",
                        "time": day,
                        "kind": "open_order",
                        "entities": [prod_id],
                        "fields": {"open_units": units_open},
                        "src": [[node_id, row_idx, ["product", "day placed", "units still open"]]],
                    })
                continue

            # Variant with day, planned production, ordered
            if "day" in cols and "planned production" in cols:
                day = _parse_day(row.get("day", ""))
                planned_prod = int(row.get("planned production", "0"))
                order_qty = int(row.get("ordered", "0"))
                if day is not None:
                    if planned_prod > 0:
                        result.append({
                            "id": f"{prod_id}_planned_prod_day_{day}",
                            "time": day,
                            "kind": "planned_production",
                            "entities": [prod_id],
                            "fields": {"produced": planned_prod},
                            "src": [[node_id, row_idx, ["day", "product", "planned production"]]],
                        })
                    if order_qty > 0:
                        result.append({
                            "id": f"{prod_id}_order_future_day_{day}",
                            "time": day,
                            "kind": "order",
                            "entities": [prod_id],
                            "fields": {"ordered": order_qty},
                            "src": [[node_id, row_idx, ["day", "product", "ordered"]]],
                        })
                continue

            # Fallback: attempt to read any 'ordered' or 'planned production' numbers
            if "planned production" in cols:
                day = _parse_day(row.get("day", ""))
                planned_prod = int(row.get("planned production", "0"))
                if day is not None and planned_prod > 0:
                    result.append({
                        "id": f"{prod_id}_planned_prod_day_{day}",
                        "time": day,
                        "kind": "planned_production",
                        "entities": [prod_id],
                        "fields": {"produced": planned_prod},
                        "src": [[node_id, row_idx, ["day", "product", "planned production"]]],
                    })
            if "ordered" in cols:
                day = _parse_day(row.get("day", ""))
                order_qty = int(row.get("ordered", "0"))
                if day is not None and order_qty > 0:
                    result.append({
                        "id": f"{prod_id}_order_future_day_{day}",
                        "time": day,
                        "kind": "order",
                        "entities": [prod_id],
                        "fields": {"ordered": order_qty},
                        "src": [[node_id, row_idx, ["day", "product", "ordered"]]],
                    })

    return result

# ------------------------------------------------------------------
# 4. Outcomes
# ------------------------------------------------------------------
def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return the list of outcome records for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Map child titles to nodes
    nodes_map = {node_by_id(doc, cid)["title"]: node_by_id(doc, cid)
                 for cid in scope_node.get("children", [])
                 if node_by_id(doc, cid)}

    result = []

    # Events list
    events_list = None
    for key, node in nodes_map.items():
        if key.endswith(": Events") and node.get("kind") == "list":
            events_list = node
            break
    if events_list:
        node_id = events_list["node_id"]
        lines = events_list.get("lines", [])
        for line_idx, line in enumerate(lines):
            cap = _parse_capacity_line(line)
            if cap:
                day, used, total = cap
                result.append({
                    "time": day,
                    "kind": "capacity_reached",
                    "entities": [],
                    "value": None,
                    "fields": {"used_capacity_kg": used, "capacity_kg": total},
                    "src": [[node_id, line_idx]],
                })
            runout = _parse_runout_line(line)
            if runout:
                day, prod, back = runout
                result.append({
                    "time": day,
                    "kind": "runs_out_of_stock",
                    "entities": [prod],
                    "value": None,
                    "fields": {"backordered_units": back},
                    "src": [[node_id, line_idx]],
                })
            full_back = _parse_full_backorder_line(line)
            if full_back:
                day, prod, back = full_back
                result.append({
                    "time": day,
                    "kind": "fully_backordered",
                    "entities": [prod],
                    "value": None,
                    "fields": {"backordered_units": back, "shipped": 0},
                    "src": [[node_id, line_idx]],
                })
            backlog = _parse_backlog_cleared_line(line)
            if backlog:
                day, prod = backlog
                result.append({
                    "time": day,
                    "kind": "backlog_cleared",
                    "entities": [prod],
                    "value": None,
                    "fields": {},
                    "src": [[node_id, line_idx]],
                })

    # Ledger outcomes
    ledger_table = nodes_map.get(f"{scope}: Daily ledger")
    if ledger_table:
        node_id = ledger_table["node_id"]
        for row_idx, row in table_rows(ledger_table):
            day = _parse_day(row.get("day", ""))
            prod_id = row.get("product")
            if day is None or not prod_id:
                continue
            result.append({
                "time": day,
                "kind": "ledger",
                "entities": [prod_id],
                "value": None,
                "fields": {
                    "produced": int(row.get("produced", "0")),
                    "ordered": int(row.get("ordered", "0")),
                    "shipped": int(row.get("shipped", "0")),
                    "backordered": int(row.get("backordered", "0")),
                    "stock": int(row.get("stock", "0")),
                },
                "src": [[node_id, row_idx, ["day", "product", "produced", "ordered", "shipped", "backordered", "stock"]]],
            })

    return result

# ------------------------------------------------------------------
# 5. Params
# ------------------------------------------------------------------
def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return constants stated in the document for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return {}

    txt = scope_node.get("text", "")
    m = re.search(r"Daily dispatch capacity: ([\d,]+) kg", txt)
    if not m:
        return {}
    return {"daily_dispatch_capacity_kg": int(m.group(1).replace(",", ""))}
